type DesignProposal = { summary:string; parts:Part[]; wires:Wire[]; notes:string[] };
function planFromInstruction(raw:string, existing:Part[]):DesignProposal {
  const text=raw.toLowerCase();
  const aliases:Record<string,string[]>={
    power:['power supply','voltage source','dc source','24 v','12 v','48 v','supply'],
    battery:['battery','cell','battery pack'],ground:['ground','earth','reference','gnd','pe'],
    resistor:['resistor','resistance','ohm'],'variable-resistor':['variable resistor','rheostat'],
    potentiometer:['potentiometer','pot'],capacitor:['capacitor','capacitance'],
    'polarized-capacitor':['electrolytic capacitor','polarized capacitor'],inductor:['inductor','coil'],
    lamp:['lamp','light','indicator'],led:['led','light emitting diode'],diode:['diode'],
    'zener-diode':['zener'],switch:['switch','contact'],'push-button-no':['push button','pushbutton','normally open'],
    'push-button-nc':['normally closed push button','nc pushbutton'],'relay-coil':['relay coil','relay'],
    'contactor-coil':['contactor coil','contactor'],motor:['motor'],'three-phase-motor':['three phase motor','3 phase motor','three-phase motor'],
    terminal:['terminal'],'terminal-block':['terminal block','terminal strip'],connector:['connector'],fuse:['fuse'],
    'circuit-breaker':['circuit breaker','breaker','mcb'],'voltage-source-ac':['ac source','ac voltage','230 v ac','mains source'],
    'current-source':['current source'],'npn-transistor':['npn','npn transistor'],'pnp-transistor':['pnp','pnp transistor'],
    nmos:['nmos','n-channel mosfet','mosfet'],pmos:['pmos','p-channel mosfet'],'op-amp':['op amp','opamp','operational amplifier'],
    plc:['plc'],'plc-input':['plc input','digital input'],'plc-output':['plc output','digital output'],
    sensor:['sensor'],'emergency-stop':['emergency stop','e-stop'],'solar-panel':['solar panel','photovoltaic panel'],
    inverter:['inverter'],transformer:['transformer']
  };
  const matched=componentLibrary.filter(item=>{
    const terms=[item.id.replaceAll('-',' '),item.id,item.label.toLowerCase(),...(aliases[item.id]||[])];
    if(item.id==='power')return terms.some(term=>text.includes(term))||/\b(12|24|48)\s*v\b/.test(text);
    if(item.id==='battery')return /\bbattery\b|\bcell\b/.test(text);
    return terms.some(term=>term.length>1&&text.includes(term));
  }).filter(item=>!['text-note','net-label','wire-crossing','wire-label'].includes(item.id));
  const expanded:typeof componentLibrary=[];
  for(const item of matched){
    const rawId=item.id.replaceAll('-','[- ]');
    const countMatch=text.match(new RegExp('(\\d+)\\s*(?:x\\s*)?'+rawId+'s?\\b'));
    const quantity=Math.min(100,Math.max(1,Number(countMatch?.[1]||1)));
    for(let i=0;i<quantity;i++)expanded.push(item);
  }
  if(!expanded.length)throw new Error('No supported component found. Try: “create a 24 V circuit with a switch, 1 kΩ resistor and LED”.');
  const counts:Record<string,number>={};
  const parts=expanded.slice(0,100).map((item,i)=>{
    counts[item.id]=(counts[item.id]||0)+1;
    const defaultValue=item.id==='power'&&/\b12\s*v\b/.test(text)?'12 V DC':item.id==='power'&&/\b48\s*v\b/.test(text)?'48 V DC':item.defaultValue;
    return {id:uid(),type:item.id,x:220+i*110,y:item.id.includes('ground')?340:200,ref:item.prefix+(existing.filter(p=>p.type===item.id).length+counts[item.id]),value:defaultValue} as Part;
  });
  const wires:Wire[]=[];
  if(/\b(connect|wire|series|circuit|between)\b/.test(text)){
    const line=parts.filter(p=>!p.type.includes('ground')&&!['text-note','net-label','wire-label','junction'].includes(p.type));
    for(let i=0;i<line.length-1;i++)wires.push({id:uid(),x1:line[i].x+38,y1:line[i].y,x2:line[i+1].x-38,y2:line[i+1].y});
  }
  return {summary:'Proposed '+parts.length+' component(s)'+(wires.length?' and '+wires.length+' wire segment(s)':''),parts,wires,notes:['Generated from a local deterministic command parser, not a connected LLM.','Only component types with explicit simulation models can be analyzed; inspect wiring and parameters.','No electrical safety, standards or installation verification has been performed.']};
}
