  const openIndustrialPackage=()=>{const p=createIndustrialFacilityPackage({name:projectName||undefined});setEngineeringPackage(p);setStatus('Preliminary industrial facility package generated with explicit assumptions')};
  const openSubstationPackage=()=>{setEngineeringPackage(createSmartSubstationPackage());setStatus('Preliminary smart-substation architecture package generated')};
  const downloadEngineeringJson=()=>{if(!engineeringPackage)return;const blob=new Blob([JSON.stringify(engineeringPackage,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='voltpro-engineering-package.json';a.click();URL.revokeObjectURL(url);setStatus('Engineering package JSON exported')};
  const downloadEngineeringCsv=(section:string)=>{if(!engineeringPackage)return;const csv=packageToCsv(engineeringPackage,section);if(!csv){setStatus('This package section has no tabular rows');return;}const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='voltpro-'+section.replace(/([A-Z])/g,'-$1').toLowerCase()+'.csv';a.click();URL.revokeObjectURL(url);setStatus(section+' CSV exported')};
  const downloadEngineeringSld=()=>{if(!engineeringPackage)return;const blob=new Blob([renderSingleLineSvg(engineeringPackage)],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='voltpro-concept-single-line.svg';a.click();URL.revokeObjectURL(url);setStatus('Concept single-line SVG exported')};
  const downloadEngineeringLayout=()=>{if(!engineeringPackage)return;const svg=renderSiteLayoutSvg(engineeringPackage);if(!svg){setStatus('This package does not include facility building zones');return;}const blob=new Blob([svg],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='voltpro-concept-site-layout.svg';a.click();URL.revokeObjectURL(url);setStatus('Concept site-layout SVG exported')};
  const downloadEngineeringIfc=()=>{if(!engineeringPackage)return;try{downloadText('voltpro-engineering-concept.ifc',exportEngineeringPackageIfc4(engineeringPackage),'application/x-step');setStatus('Engineering-package IFC4 massing/equipment proxies exported; coordinates and generic geometry require BIM coordination review.')}catch(error){setStatus('Engineering IFC export failed: '+(error instanceof Error?error.message:'unknown error'))}};
  const downloadEngineeringIsometric=()=>{if(!engineeringPackage)return;const svg=renderEngineeringIsometricSvg(engineeringPackage);if(!svg){setStatus('This package has no building-zone/equipment coordinates for a 3D massing view');return;}downloadText('voltpro-isometric-3d-massing.svg',svg,'image/svg+xml');setStatus('Isometric 3D concept massing exported; use IFC4 export for BIM exchange.')};
  const downloadEngineeringGltf=()=>{if(!engineeringPackage)return;try{downloadText('voltpro-engineering-concept.gltf',exportEngineeringPackageGltf(engineeringPackage),'model/gltf+json');setStatus('3D glTF concept model exported with building and equipment meshes; geometry remains concept-level and uncoordinated.')}catch(error){setStatus('3D model export failed: '+(error instanceof Error?error.message:'unknown error'))}};
  const downloadEngineeringClashes=()=>{try{const spatialModel=engineeringPackage||createSchematic3DPackage(documentData());const report={...analyzeEngineeringPackageClashes(spatialModel),source:engineeringPackage?'engineering concept package':'active schematic 3D proxy model'};downloadText('voltpro-spatial-clash-check.json',JSON.stringify(report,null,2),'application/json');const csv=['kind,severity,first,second,overlapX_M,overlapY_M,overlapZ_M',...report.overlaps.map(x=>[x.kind,x.severity,JSON.stringify(x.first),JSON.stringify(x.second),x.overlapX_M,x.overlapY_M,x.overlapZ_M??''].join(','))].join('\n');downloadText('voltpro-spatial-clash-check.csv',csv,'text/csv');setStatus(report.status+' · '+report.overlapCount+' spatial finding(s) in '+report.source+'; cable trays, service routing, access envelopes and maintainability clearances remain unverified.')}catch(error){setStatus('Spatial clash check failed: '+(error instanceof Error?error.message:'unknown error'))}};
  const downloadText=(filename:string,content:string,type='text/plain;charset=utf-8')=>{const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)};
